const GROUPS={
 'Document & metadata':'html head body title base link meta style',
 'Sections & landmarks':'address article aside footer header hgroup main nav search section h1 h2 h3 h4 h5 h6',
 'Text & meaning':'a abbr b bdi bdo br cite code data dfn em i kbd mark q rp rt ruby s samp small span strong sub sup time u var wbr',
 'Blocks & lists':'blockquote dd div dl dt figcaption figure hr li menu ol p pre ul',
 'Images & media':'area audio canvas embed iframe img map object picture source track video',
 'Tables':'caption col colgroup table tbody td tfoot th thead tr',
 'Forms & controls':'button datalist fieldset form input label legend meter optgroup option output progress select selectedcontent textarea',
 'Disclosure & dialogs':'details dialog summary',
 'Scripts & components':'noscript script slot template ins del'
};
const categoryOf=n=>Object.keys(GROUPS).find(k=>GROUPS[k].split(' ').includes(n))||'Other';
const T=' data-lab-target';
const image=`data:image/svg+xml,${encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="360" height="160"><rect width="360" height="160" fill="#2334ea"/><rect x="180" width="180" height="160" fill="#e7b442"/><text x="24" y="85" font-family="sans-serif" font-size="24" fill="white">Sample image</text></svg>')}`;
function sample(name){return `<${name}${T}>${({a:'Explore HTML',abbr:'HTML',b:'Key term',bdi:'مرحبا',bdo:'Text direction',cite:'A book title',code:'const total = 3;',data:'Three',dfn:'Semantic HTML',em:'really',i:'Homo sapiens',kbd:'Ctrl + S',mark:'Found match',q:'A short quotation',s:'Old price: $50',samp:'Build complete',small:'Terms apply.',span:'A phrase',strong:'Keep this file.',sub:'2',sup:'2',time:'October 4, 2026',u:'Speling',var:'x',ins:'New wording',del:'Old wording'})[name]||'Example text'}</${name}>`;}
function example(n){
 let html='',note='',chain=[n],challenge='Edit the text, then change an attribute and compare the result.',limit='',access='Use the element for its meaning. Styling alone does not give another element the same semantics.';
 const set=(h,why,c,tryThis,lim)=>{html=h;note=why;chain=c||[n];challenge=tryThis||challenge;limit=lim||'';};
 if('a abbr b bdi bdo cite code data dfn em i kbd mark q s samp small span strong sub sup time u var ins del'.split(' ').includes(n)){
  html=`<p class="supporting">A sentence with ${sample(n)} in its context.</p>`;note='This inline element sits inside a paragraph. Compare its meaning and default appearance with the surrounding text.';chain=['p',n];
  const extras={a:' href="#destination"',abbr:' title="HyperText Markup Language"',bdo:' dir="rtl"',data:' value="3"',time:' datetime="2026-10-04"',del:' datetime="2026-10-03"',ins:' datetime="2026-10-04"'};
  if(extras[n])html=html.replace(T,T+extras[n]);
  if(n==='a'){html+='<p id="destination">Link destination</p>';limit='Navigation is intercepted in this lab; the frame reports the destination instead.';access='Use a descriptive link label. Use a button for actions that do not navigate.';}
 }
 if(/^h[1-6]$/.test(n))set(`<article class="supporting"><${n}${T}>Example heading</${n}><p>The paragraph belongs to this section.</p></article>`,'A heading names a section of content. The level expresses hierarchy, not just font size.',['article',n,'p'],'Compare h1 through h6. Notice that the heading level changes even if CSS makes them look alike.');
 const layout={article:'A self-contained article',aside:'Related information',footer:'Page or section footer',header:'Page or section introduction',main:'The primary page content',nav:'Navigation',section:'A named section',address:'Contact: hello@example.test',search:'Search the site',div:'A generic container'};
 if(n in layout){let child=n==='nav'?'<a href="#news">News</a> · <a href="#contact">Contact</a>':n==='search'?'<form><label for="query">Search</label><input id="query" type="search"><button>Search</button></form>':`<h2>${layout[n]}</h2><p>Supporting content makes the purpose clear.</p>`;set(`<${n}${T}>${child}</${n}>`,'The target contains real supporting content. Semantic sections and landmarks communicate structure; div supplies no special meaning.',[n,n==='search'?'form':'h2','p']);access='Give sections useful headings. Use one visible main landmark for the primary content. Give multiple navigation landmarks distinct labels.';}
 const maps={
 p:['<section class="supporting"><h2>A short story</h2><p'+T+'>A paragraph groups a complete thought.</p></section>','The paragraph belongs to a section and contains phrasing content. Putting a block such as a div inside p causes the parser to close the paragraph.',['section','p']],
 blockquote:['<figure class="supporting"><blockquote'+T+' cite="https://example.test/source"><p>A longer quotation belongs in its own block.</p></blockquote><figcaption>Attribution: Example author</figcaption></figure>','The quote contains a paragraph; the visible attribution is separate. The cite attribute stores a source URL but does not show an attribution.',['figure','blockquote','p','figcaption']],
 pre:['<pre'+T+'>Line one\n    Indented line two\nLine three</pre>','Whitespace and line breaks are preserved. Use code inside pre when the content is source code.',['pre']],
 hr:['<p>First topic.</p><hr'+T+'><p>A new topic begins.</p>','The rule marks a thematic break between content, not merely a decorative line.',['p','hr','p']],
 br:['<p>First address line<br'+T+'>Second address line</p>','A line break belongs inside text. It should not replace paragraphs or layout spacing.',['p','br']],
 wbr:['<p style="width:150px">averylongword<wbr'+T+'>withanoptionalbreak</p>','A narrow text container makes the optional word-break opportunity observable. Wbr does not always create a visible break.',['p','wbr']],
 hgroup:['<hgroup'+T+'><h1>HTML in context</h1><p>A subtitle for the heading</p></hgroup>','Hgroup groups a heading with related subtitles or taglines. It is not a wrapper for multiple heading levels.',['hgroup','h1','p']],
 details:['<details'+T+' open><summary>Delivery information</summary><p>Your package arrives in three days.</p></details>','Details needs a summary that labels its disclosure control, followed by the content it reveals.',['details','summary','p'],'Remove open, then click the summary to expand the content.'],
 summary:['<details class="supporting"><summary'+T+'>Delivery information</summary><p>Your package arrives in three days.</p></details>','Summary is the label of its parent details element; it does not create a disclosure by itself.',['details','summary','p'],'Click the summary. Try changing its label and using the keyboard.'],
 dialog:['<button type="button" onclick="document.querySelector(\'dialog\').showModal()">Open modal</button><dialog'+T+'><h2>Confirm your choice</h2><p>A dialog can be modal or non-modal.</p><button type="button" onclick="this.closest(\'dialog\').close()">Close</button></dialog>','Dialog needs an opening action. The button uses showModal(); the close button restores the closed state. Setting open alone creates a non-modal dialog.',['button','dialog','button'],'Open the modal and try Escape. Compare this with adding the open attribute.'],
 fieldset:['<form><fieldset'+T+'><legend>Delivery method</legend><label><input type="radio" name="delivery" checked> Standard</label><label><input type="radio" name="delivery"> Express</label></fieldset></form>','The fieldset groups related form controls. Legend provides the name for the group.',['form','fieldset','legend','input'],'Set disabled to disable the group of controls.'],
 legend:['<fieldset class="supporting"><legend'+T+'>Contact details</legend><label for="contact">Email</label><input id="contact" type="email"></fieldset>','Legend must label its fieldset and normally appears as its first child. It provides the group name.',['fieldset','legend','input']],
 form:['<form'+T+' action="/signup" method="get"><label for="email">Email address</label><input id="email" name="email" type="email" required><button type="submit">Submit</button></form>','A form ties controls to a submission action. Named fields supply submitted data; native validation happens before the submit event.',['form','label','input','button'],'Submit an invalid email, then a valid one.','Submissions are intercepted and displayed here; no server receives the form.'],
 input:['<form><label for="field">Your value</label><input'+T+' id="field" name="field" type="text" placeholder="Type here"><button>Submit</button></form>','An input needs a label and often belongs to a form. Its type changes the control and which other attributes apply.',['form','label','input'],'Try text, number, range, checkbox, date, and email. The same input element behaves differently.'],
 label:['<form><label'+T+' for="field">Email address</label><input id="field" name="email" type="email"></form>','The for attribute connects the label to a control with the matching id. Clicking the label should focus the control.',['form','label','input'],'Change for to a different id, then click the label and compare.'],
 button:['<form><label for="name">Name</label><input id="name" name="name" required><button'+T+' type="submit">Submit</button></form>','Inside a form, a button defaults to submission. An explicit type distinguishes submit, reset, and an ordinary action.',['form','input','button'],'Try submit, reset, and button. Enter text before testing reset.'],
 textarea:['<form><label for="message">Message</label><textarea'+T+' id="message" name="message" rows="3" cols="24" placeholder="Write a message"></textarea></form>','Textarea is a labelled multiline control. Its initial text belongs between its tags, rather than in a value attribute.',['form','label','textarea']],
 select:['<label for="choice">Delivery</label><select'+T+' id="choice" name="delivery"><option value="standard">Standard</option><option value="express">Express</option></select>','A select needs option children and a label. Options provide visible labels and submitted values.',['label','select','option'],'Try multiple or size to turn the dropdown into a list box.'],
 option:['<label for="choice">Delivery</label><select id="choice" class="supporting"><option'+T+' value="standard">Standard</option><option value="express">Express</option></select>','Option belongs inside a select, optgroup, or datalist. Here its selected, disabled, and value attributes affect a real select.',['select','option'],'Add disabled or selected. Reopen the menu to see the effect.'],
 optgroup:['<label for="city">Destination</label><select id="city"><optgroup'+T+' label="Massachusetts"><option>Salem</option><option>Boston</option></optgroup><optgroup label="Maine"><option>Portland</option></optgroup></select>','Optgroup groups option children within a select. Its label appears as a group heading in the menu.',['select','optgroup','option']],
 datalist:['<label for="browser">Choose or type a browser</label><input id="browser" list="browsers"><datalist'+T+' id="browsers"><option value="Firefox"></option><option value="Chrome"></option><option value="Safari"></option></datalist>','Datalist supplies suggestions to an input whose list attribute matches its id. It is not a standalone dropdown and does not restrict input to its suggestions.',['input[list]','datalist[id]','option'],'Focus the input and type C to look for a suggestion.'],
 selectedcontent:['<label for="custom">Delivery</label><select id="custom" style="appearance:base-select"><button><selectedcontent'+T+'></selectedcontent></button><option value="standard">📦 Standard</option><option value="express">⚡ Express</option></select>','Selectedcontent belongs in the button of a customizable select and mirrors the selected option. This newer feature needs browser support for customizable selects.',['select','button','selectedcontent','option'],'Change the selected option.','A browser without customizable-select support may fall back to an ordinary select.'],
 output:['<form oninput="document.querySelector(\'output\').value=Number(document.querySelector(\'#amount\').value)*2"><label for="amount">Amount</label><input id="amount" type="range" value="25"><p>Double: <output'+T+' for="amount">50</output></p></form>','Output identifies a calculation result. JavaScript performs the calculation; the for attribute relates the output to its input.',['form','input','output'],'Move the slider and watch the calculated result.'],
 meter:['<label for="level">Storage used</label><meter'+T+' id="level" min="0" max="100" low="20" high="80" optimum="10" value="65">65%</meter>','Meter represents a measurement within a known range. Min, max, low, high, and optimum define how the value is interpreted.',['label','meter'],'Change value to 10, 65, then 95.'],
 progress:['<label for="task">Upload progress</label><progress'+T+' id="task" max="100" value="40">40%</progress>','Progress represents task completion. Removing value makes the progress indeterminate; meter describes a measurement instead.',['label','progress'],'Remove value to compare determinate and indeterminate progress.'],
 iframe:['<iframe'+T+' title="Example nested document" srcdoc="&lt;h2&gt;Another document&lt;/h2&gt;&lt;p&gt;This content lives in its own frame.&lt;/p&gt;"></iframe>','Iframe embeds an independent document. Srcdoc supplies that document directly; title gives the frame an accessible name.',['iframe','separate document'],'Edit srcdoc to change the nested page.','External sites may block embedding; this example uses a local document.'],
 canvas:['<canvas'+T+' width="320" height="120">Canvas drawing: three sample rectangles.</canvas><script>const c=document.querySelector("canvas").getContext("2d");["#2334ea","#e7b442","#1b8066"].forEach((color,i)=>{c.fillStyle=color;c.fillRect(i*105,10,95,90)});</script>','Canvas is a bitmap drawing surface. A script must draw into it; HTML text provides fallback content. Width and height set bitmap dimensions.',['canvas','drawing script'],'Change width or height and compare bitmap dimensions with CSS sizing.'],
 template:['<template'+T+'><p>A reusable fragment.</p></template><button type="button" onclick="document.querySelector(\'#copies\').append(document.querySelector(\'template\').content.cloneNode(true))">Clone template</button><div id="copies"></div>','Template stores inert content. Nothing appears until a script clones its content into the active document.',['template','clone action','rendered fragment'],'Click Clone template twice. Edit the fragment and run it again.'],
 slot:['<div id="host"><span slot="greeting">Hello from light DOM</span></div><template id="shadow"><p>Inside the component: <slot'+T+' name="greeting">Fallback greeting</slot></p></template><script>document.querySelector("#host").attachShadow({mode:"open"}).append(document.querySelector("#shadow").content.cloneNode(true));</script>','A slot receives content inside a shadow tree. The light-DOM element’s slot attribute must match this slot’s name.',['host','shadow tree','slot'],'Change name to something else to reveal the fallback text.'],
 script:['<p id="result">Waiting for script…</p><script'+T+'>document.querySelector("#result").textContent="The script ran inside this preview.";</script>','Script has no visual box; its effect appears in the paragraph it updates. Scripts run only inside the isolated preview.',['script','p#result'],'Change the text produced by the script and run the example.'],
 noscript:['<noscript'+T+'><p>This fallback is shown when scripting is disabled.</p></noscript><p>Scripting is enabled in this preview.</p>','Noscript is fallback content for a document without scripting. This preview enables scripts, so the fallback is intentionally absent.',['noscript','script-enabled document'],'Read the markup and compare the fallback with the scripting-enabled message.','Disable JavaScript in a separate exported document to test the fallback visually.']
 };
 if(maps[n])set(...maps[n]);
 if(['ol','ul','menu','li'].includes(n)){let parent=n==='li'?'ul':n;html=`<${parent}${n==='li'?' class="supporting"':T}><li${n==='li'?T:''}>First item</li><li>Second item</li><li>Third item</li></${parent}>`;note='The list container supplies the context; li supplies each item. Ol expresses order, while ul and menu do not number the items.';chain=[parent,'li'];challenge=n==='ol'?'Try start and reversed.':'Edit the items and compare list containers.';}
 if(['dl','dt','dd'].includes(n)){html=`<dl${n==='dl'?T:''}><dt${n==='dt'?T:''}>Element</dt><dd${n==='dd'?T:''}>A building block with meaning.</dd><dt>Attribute</dt><dd>A setting on an element.</dd></dl>`;note='Dl groups terms and descriptions. Dt supplies the term; dd supplies its associated description.';chain=['dl','dt','dd'];}
 if(['figure','figcaption'].includes(n)){html=`<figure${n==='figure'?T:''}><img src="${image}" alt="Blue and gold sample image"><figcaption${n==='figcaption'?T:''}>A caption associated with this image.</figcaption></figure>`;note='Figure groups self-contained content with its optional figcaption. Figcaption must be its first or last child.';chain=['figure','img','figcaption'];}
 if(['ruby','rt','rp'].includes(n)){html=`<p><ruby${n==='ruby'?T:''}>漢<rp${n==='rp'?T:''}>(</rp><rt${n==='rt'?T:''}>kan</rt><rp>)</rp></ruby></p>`;note='Ruby groups base text with rt annotations. Rp supplies fallback parentheses for browsers without ruby layout.';chain=['ruby','rp','rt'];limit='Rp fallback parentheses are normally hidden in browsers that support ruby.';}
 if(categoryOf(n)==='Tables'){
  html=`<table${n==='table'?T:''}><caption${n==='caption'?T:''}>Workshop supplies</caption><colgroup${n==='colgroup'?T:''}><col${n==='col'?T:''} span="1" style="background:#eef1ff"><col></colgroup><thead${n==='thead'?T:''}><tr><th${n==='th'?T:''} scope="col">Item</th><th scope="col">Quantity</th></tr></thead><tbody${n==='tbody'?T:''}><tr${n==='tr'?T:''}><td${n==='td'?T:''}>Notebooks</td><td>3</td></tr><tr><td>Pencils</td><td>12</td></tr></tbody><tfoot${n==='tfoot'?T:''}><tr><th scope="row">Total</th><td>15</td></tr></tfoot></table>`;
  note='This complete table supplies the structure required by the target. Cells belong to rows; rows belong to a table or row group. Column definitions appear before row groups.';chain=['table',...(['col','colgroup'].includes(n)?['colgroup','col']:['tbody','tr','th / td'])];challenge='Change the target’s attribute and compare its effect within the complete table.';access='Use caption to name the table and th with scope for row or column headers. Do not use tables purely for page layout.';
  if(n==='col'||n==='colgroup')limit='Column elements do not contain cells; only selected CSS properties affect their corresponding columns.';
 }
 if(['img','picture','source'].includes(n)){html=n==='img'?`<img${T} src="${image}" alt="Blue and gold sample image" width="320" height="142">`:`<picture${n==='picture'?T:''}><source${n==='source'?T:''} media="(min-width: 500px)" srcset="${image}"><img src="${image.replace(encodeURIComponent("#2334ea"),encodeURIComponent("#6b2cbf"))}" alt="Blue and gold sample image" width="320"></picture>`;note=n==='img'?'The image has alternative text and intrinsic dimensions. The alt text conveys its meaning when it cannot be seen.':'Picture needs an img fallback. Source supplies a candidate; it never draws an image on its own. Media conditions select a source.';chain=n==='img'?['img']:['picture','source','img'];challenge='Change alt or width. For picture, resize the preview and inspect its source conditions.';access='Write alt text for the image’s purpose. Use alt="" for decorative images.';}
 if(['map','area'].includes(n)){html=`<img src="${image}" alt="Two linked sample regions" usemap="#regions" width="360" height="160"><map${n==='map'?T:''} name="regions"><area${n==='area'?T:''} shape="rect" coords="0,0,180,160" href="#blue" alt="Blue region"><area shape="rect" coords="180,0,360,160" href="#gold" alt="Gold region"></map>`;note='Img connects to map using usemap and a matching name. Area defines a clickable region using coordinates relative to the image.';chain=['img[usemap]','map[name]','area'];challenge='Click each colored region, then change coords.';access='Every linked area needs meaningful alt text. Fixed map coordinates need care when images are resized.';}
 if(['audio','video','track'].includes(n)){let media=n==='audio'?'audio':'video';html=`<${media}${n===media?T:''} controls ${media==='video'?'width="320"':''}><source src="${media==='audio'?'tone.wav':'sample.mp4'}" type="${media==='audio'?'audio/wav':'video/mp4'}">${media==='video'?`<track${n==='track'?T:''} kind="captions" src="captions.vtt" srclang="en" label="English" default>`:''}Your browser does not support this media.</${media}>`;note='The player needs a playable source. Track supplies timed text to a video, rather than standalone visible content. Local sample media is provided.';chain=[media,'source',...(media==='video'?['track']:[])];challenge='Play the sample. Try muted, loop, controls, or playback captions.';limit='Autoplay can be blocked by browser policy. Captions may depend on browser handling of isolated frames.';access='Provide captions for meaningful video audio and a transcript for audio. Avoid starting audio automatically.';}
 if(['object','embed'].includes(n)){html=n==='object'?`<object${T} data="${image}" type="image/svg+xml" width="320" height="142"><p>Fallback when embedding fails.</p></object>`:`<embed${T} src="${image}" type="image/svg+xml" width="320" height="142">`;note='The embedded resource and its MIME type determine the renderer. Object can include fallback content; embed is a void element.';chain=[n,'embedded resource'];limit='Plugin support and external-resource permissions vary by browser. This sample embeds an image.';}
 if(categoryOf(n)==='Document & metadata'){
 const head={title:'<title'+T+'>My document title</title>',base:'<base'+T+' href="https://example.test/folder/">',link:'<link'+T+' rel="stylesheet" href="sample.css">',meta:'<meta'+T+' name="description" content="A sample document description.">',style:'<style'+T+'>p { color: #2334ea; }</style>'};
 html=`<!doctype html>\n<html${n==='html'?T:''} lang="en">\n<head${n==='head'?T:''}>\n${head[n]||'<title>Sample document</title>'}\n</head>\n<body${n==='body'?T:''}>\n<h1>A complete document</h1>\n<p>Metadata belongs in head; visible content belongs in body.</p>\n<a href="chapter.html">Relative link</a>\n</body>\n</html>`;
 note='A complete document supplies the correct head and body context. Metadata usually has no visible box; the preview’s inspection panel reports what the browser parsed.';chain=['html','head',n==='body'?'body':n];challenge=n==='style'?'Change the style rule and watch the paragraph.':'Change the attribute or content and read the document inspection panel.';limit='This is a nested document. Title does not change the parent tab; metadata does not demonstrate search-engine behavior. External resource loading can be blocked.';
 }
 if(!html)throw new Error('No example for '+n);
 return {html,note,chain,challenge,limit,access};
}
const ATTRIBUTE_SAMPLES={type:['text','email','number','checkbox','range','date','color','file','password','radio','submit','reset','button'],dir:['ltr','rtl','auto'],lang:['en','es','ar'],contenteditable:['true','false','plaintext-only'],draggable:['true','false'],spellcheck:['true','false'],translate:['yes','no'],hidden:['','until-found'],popover:['auto','manual','hint'],popovertargetaction:['toggle','show','hide'],loading:['eager','lazy'],decoding:['auto','sync','async'],preload:['none','metadata','auto'],method:['get','post','dialog'],formmethod:['get','post','dialog'],enctype:['application/x-www-form-urlencoded','multipart/form-data','text/plain'],autocomplete:['on','off','email','name','new-password'],inputmode:['text','numeric','decimal','email','tel','url','search','none'],enterkeyhint:['enter','done','go','next','search','send'],wrap:['soft','hard'],shape:['rect','circle','poly','default'],scope:['col','row','colgroup','rowgroup'],kind:['captions','subtitles','descriptions','chapters','metadata'],target:['_self','_blank','_parent','_top'],closedby:['any','closerequest','none'],command:['show-modal','close','request-close','toggle-popover','show-popover','hide-popover'],rel:['stylesheet','alternate','noopener','noreferrer'],name:['example','description','regions'],value:['25','50','75'],min:['0','10'],max:['100','50'],step:['1','5','0.5'],rows:['2','4','8'],cols:['20','40','60'],size:['1','3','5'],start:['1','5','10'],tabindex:['0','-1'],colspan:['1','2'],rowspan:['1','2'],span:['1','2'],width:['160','320','480'],height:['80','160','240'],maxlength:['5','20'],minlength:['3','10'],pattern:['[A-Za-z]+','[0-9]{3}'],placeholder:['Type here','Your email'],class:['highlight','large',''],style:['color: #2334ea;','background: #fff3ce; padding: 12px;','font-size: 24px;'],title:['Extra information','A descriptive title'],id:['field','example'],for:['field','amount','missing'],list:['browsers','missing'],href:['#destination','https://example.test/','chapter.html'],src:[image,'missing-image.png'],srcset:[image],alt:['Blue and gold sample image','','Alternative text'],datetime:['2026-10-04','2026-10-04T13:30'],action:['/signup','/search'],formaction:['/signup','/search'],accept:['image/*','.pdf','audio/*'],media:['(min-width: 500px)','(max-width: 500px)','print'],coords:['0,0,180,160','180,0,360,160'],usemap:['#regions','#missing'],label:['New group','Delivery'],slot:['greeting','other'],shadowrootmode:['open','closed'],colorspace:['limited-srgb','display-p3'],color:['#2334ea','#e7b442'],http_equiv:['refresh'],content:['A document description'],charset:['utf-8'],data:[image],open:[''],disabled:[''],checked:[''],selected:[''],required:[''],multiple:[''],reversed:[''],download:['sample-file'],sandbox:['','allow-scripts'],allow:['fullscreen'],popovertarget:['popover-demo'],commandfor:['dialog-demo'],form:['example-form'],headers:['column-item'],as:['style','image','script'],crossorigin:['anonymous','use-credentials'],referrerpolicy:['no-referrer','same-origin','strict-origin-when-cross-origin'],fetchpriority:['auto','high','low'],blocking:['render'],writingsuggestions:['true','false'],autocorrect:['on','off'],autocapitalize:['none','sentences','words','characters'],headingoffset:['0','1','2'],headingreset:[''],itemscope:[''],itemprop:['name','description'],itemtype:['https://schema.org/Person'],itemid:['https://example.test/person/1'],itemref:['extra'],nonce:['example-nonce'],integrity:['sha256-example'],is:['custom-example'],sizes:['32x32','any'],imagesizes:['100vw'],imagesrcset:[image],srclang:['en','es'],ping:['https://example.test/ping'],hreflang:['en','es'],low:['20','40'],high:['60','80'],optimum:['10','90'],dirname:['field.dir'],accesskey:['s','x'],abbr:['Qty','Item'],accept_charset:['UTF-8'],srcdoc:['<h2>Nested page</h2><p>Hello.</p>']};
const attributeCategory=a=>a.event?'Event handlers':a.global?'Global attributes':a.name.startsWith('shadowroot')?'Shadow DOM': 'Element-specific attributes';
Object.assign(ATTRIBUTE_SAMPLES,{cite:['https://example.test/source'],formenctype:['application/x-www-form-urlencoded','multipart/form-data','text/plain'],formtarget:['_self','_blank'],poster:[image],shadowrootslotassignment:['named','manual']});
